    public override void _EnterTree()
    {
        Engine.RegisterSingleton("KiwiNativeServices",this);
        LegacyResourceLoader.RegisterLegacyUids();
        _loader = new LegacyResourceLoader(); ResourceLoader.AddResourceFormatLoader(_loader, true);
    }
    private void ReleaseServices()
    {
        lock(_serviceLock){_servicePins.Clear();foreach(var service in _services.Values)service.Dispose();_services.Clear();_sourceLinks.Clear();}
    }
    public override void _ExitTree()
    {
        WorldWorkerJob.CancelAndJoinActive();
        EnvironmentGenerationJob.CancelAndJoinActive();
        BuildingGenerationJob.CancelAndJoinActive();
        EnvironmentScatterJob.CancelAndJoinActive();
        TerrainSliceJob.CancelAndJoinActive();
        NaturalGenerationJob.CancelAndJoinActive();
        TerrainDataOperations.ClearCache();
        ModelNaturalGenerator.ClearCache();
        BuildingMeshCache.ClearCache();
        TimelineMaterialLink.ClearCache();
        BasicActorDefaults.ClearCache();
        ActorUIVisual.ClearCache();
        ActorTransformationStates.ClearCaches();
        ActorAudio.ClearCaches();
        ActorVideo.ClearCaches();
        ActorImageGenerator.ClearCaches();
        ActorTextSettings.ClearCaches();
        KiwiAudioPortableCopy.ClearResources();KiwiAudioRecovery.ClearResources();EngineVariantDispatch.ClearCaches();
        ShaderSampleCatalogOperations.ClearCache();
        ShaderPreviewAssets.ClearCache();
        AudioRendererOperations.ClearCache();
        Engine.UnregisterSingleton("KiwiNativeServices");
        ReleaseServices();
        if(_loader!=null){ResourceLoader.RemoveResourceFormatLoader(_loader);_loader.Dispose();_loader=null;}
        // Drain transient managed resource wrappers while the engine is still alive.
        // Otherwise late finalizers can enter native disposal after Mono teardown.
        GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();
